#include <iostream>
#include <algorithm>
#include <numeric>
#include <cmath>
using namespace std;

long long compute_gcd(long long a, long long b) {
    while (b != 0) {
        long long t = b;
        b = a % b;
        a = t;
    }
    return a;
}

long long compute_lcm(long long a, long long b) {
    return a / compute_gcd(a, b) * b;
}

struct Fraction {
    long long num;
    long long den;
};

Fraction absolute(const Fraction& f) {
    return {abs(f.num), f.den};
}

int compare(const Fraction& a, const Fraction& b) {
    long long l = compute_lcm(a.den, b.den);
    long long na = a.num * (l / a.den);
    long long nb = b.num * (l / b.den);
    if (na == nb) return 0;
    return (na < nb) ? -1 : 1;
}

Fraction subtract(const Fraction& a, const Fraction& b) {
    long long l = compute_lcm(a.den, b.den);
    long long na = a.num * (l / a.den);
    long long nb = b.num * (l / b.den);
    long long res_num = na - nb;
    long long g = compute_gcd(abs(res_num), l);
    return {res_num / g, l / g};
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    long long x, y, n;
    cin >> x >> y >> n;
    long long g = compute_gcd(x, y);
    x /= g; y /= g;
    Fraction xy = {x, y};
    Fraction best_diff = {1000000000000LL, 1};
    Fraction best_value = {0, 0};
    for (long long b = 1; b <= n; ++b) {
        long long l = 0, r = 1000000;
        double maxv = (double)x / y + (double)best_diff.num / best_diff.den + 2;
        maxv *= b;
        r = (long long)maxv;
        while (l <= r) {
            long long mid = l + (r - l) / 2;
            Fraction candidate = {mid, b};
            Fraction diff = absolute(subtract(xy, candidate));
            int cmp = compare(diff, best_diff);
            if (cmp == 0) {
                if (candidate.den < best_value.den)
                    best_value = candidate;
                else if (candidate.den == best_value.den && candidate.num < best_value.num)
                    best_value = candidate;
            } else if (cmp < 0) {
                best_diff = diff;
                best_value = candidate;
            }
            if (compare(candidate, xy) < 0)
                l = mid + 1;
            else
                r = mid - 1;
        }
    }
    cout << best_value.num << "/" << best_value.den;
    return 0;
}
